import { createFormHook, createFormHookContexts } from "@tanstack/react-form";
import type { ReactNode } from "react";
import { lazy, Suspense } from "react";
import { Combobox } from "@/components/combobox/combobox";
import type { ComboboxOption } from "@/components/combobox/use-combobox-options";
import { formatIso, ISO_DATE, ISO_DATE_TIME, parseIso } from "@/components/date-picker/date-io";
import { FormErrorSummary } from "@/components/form/form-error-summary";
import { RequiredMark } from "@/components/form/required-mark";
import { Badge } from "@/components/ui/badge";
import { Field, FieldError, FieldLabel } from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Skeleton } from "@/components/ui/skeleton";
import { Switch } from "@/components/ui/switch";

const MultiCombobox = lazy(() =>
  import("@/components/combobox/multi-combobox").then((m) => ({ default: m.MultiCombobox })),
);
const DatePicker = lazy(() =>
  import("@/components/date-picker/date-picker").then((m) => ({ default: m.DatePicker })),
);
const DateTimePicker = lazy(() =>
  import("@/components/date-picker/date-time-picker").then((m) => ({
    default: m.DateTimePicker,
  })),
);
const DateRangePicker = lazy(() =>
  import("@/components/date-picker/date-range-picker").then((m) => ({
    default: m.DateRangePicker,
  })),
);

export const { fieldContext, formContext, useFieldContext, useFormContext } =
  createFormHookContexts();

/** 错误元素可能是服务端原始字符串或 Standard Schema issue;FieldError 只认 {message}。 */
function toFieldErrors(errors: unknown[]): { message?: string }[] {
  return errors.map((e) => (typeof e === "string" ? { message: e } : (e as { message?: string })));
}

interface ServerErrorFieldMeta {
  errorMap?: Record<string, unknown>;
}

/** `clearServerSubmitErrors` 需要的最小结构面,避免依赖 TanStack Form 的完整泛型形态。 */
interface ServerErrorForm {
  state: { fieldMeta: Record<string, ServerErrorFieldMeta | undefined> };
  setFieldMeta: (
    name: string,
    updater: (meta: ServerErrorFieldMeta) => ServerErrorFieldMeta,
  ) => void;
  setErrorMap: (map: { onSubmit?: undefined }) => void;
}

/**
 * 绕过 @tanstack/react-form 1.33.2 死锁:onSubmitAsync 注入的字段级错误不会在重提交时自清,
 * 不清则提交被永久短路。约束:onSubmit 槽位只放服务端错误,勿给 field 另挂 onSubmit 校验器。
 */
function clearServerSubmitErrors(form: ServerErrorForm): void {
  for (const name of Object.keys(form.state.fieldMeta)) {
    form.setFieldMeta(name, (meta) => ({
      ...meta,
      errorMap: { ...meta.errorMap, onSubmit: undefined },
    }));
  }
  form.setErrorMap({ onSubmit: undefined });
}

function FieldShell(props: {
  label: string;
  required?: boolean;
  orientation?: "vertical" | "horizontal";
  children: ReactNode;
}) {
  const field = useFieldContext();
  const invalid = field.state.meta.errors.length > 0;
  return (
    <Field orientation={props.orientation} data-invalid={invalid ? true : undefined}>
      <FieldLabel htmlFor={field.name}>
        {props.label}
        {props.required === true && <RequiredMark />}
      </FieldLabel>
      {props.children}
      <FieldError errors={toFieldErrors(field.state.meta.errors)} />
    </Field>
  );
}

export function TextField(props: {
  label: string;
  required?: boolean;
  type?: "text" | "email" | "password" | "date";
  disabled?: boolean;
  placeholder?: string;
  autoComplete?: string;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell label={props.label} required={props.required}>
      <Input
        id={field.name}
        name={field.name}
        type={props.type ?? "text"}
        aria-required={props.required === true || undefined}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        value={field.state.value}
        disabled={props.disabled}
        placeholder={props.placeholder}
        autoComplete={props.autoComplete}
        onBlur={field.handleBlur}
        onChange={(event) => field.handleChange(event.target.value)}
      />
    </FieldShell>
  );
}

export function NumberField(props: {
  label: string;
  required?: boolean;
  disabled?: boolean;
  step?: string;
}) {
  const field = useFieldContext<number>();
  return (
    <FieldShell label={props.label} required={props.required}>
      <Input
        id={field.name}
        name={field.name}
        type="number"
        step={props.step}
        aria-required={props.required === true || undefined}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        value={Number.isNaN(field.state.value) ? "" : String(field.state.value)}
        disabled={props.disabled}
        onBlur={field.handleBlur}
        onChange={(event) => {
          // 空串裸转 Number 是 0,会把「清空了」写成「改成 0」;映射 NaN 让 z.number() 判失败
          const raw = event.target.value;
          field.handleChange(raw.trim() === "" ? Number.NaN : Number(raw));
        }}
      />
    </FieldShell>
  );
}

export function SwitchField(props: { label: string; disabled?: boolean }) {
  const field = useFieldContext<boolean>();
  return (
    <FieldShell label={props.label} orientation="horizontal">
      <Switch
        id={field.name}
        aria-invalid={field.state.meta.errors.length > 0 || undefined}
        checked={field.state.value}
        disabled={props.disabled}
        onCheckedChange={(checked: boolean) => field.handleChange(checked)}
      />
    </FieldShell>
  );
}

export function SelectField(props: {
  label: string;
  options: { value: string; label: string }[];
  required?: boolean;
  disabled?: boolean;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell label={props.label} required={props.required}>
      <Select
        value={field.state.value}
        onValueChange={(value) => field.handleChange(value)}
        disabled={props.disabled}
      >
        <SelectTrigger
          id={field.name}
          className="w-full"
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
        >
          <SelectValue />
        </SelectTrigger>
        <SelectContent>
          {props.options.map((option) => (
            <SelectItem key={option.value} value={option.value}>
              {option.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FieldShell>
  );
}

export function DateField(props: {
  label: string;
  required?: boolean;
  disabled?: boolean;
  placeholder?: string;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell label={props.label} required={props.required}>
      <Suspense fallback={<Skeleton className="h-9 w-full" />}>
        <DatePicker
          id={field.name}
          value={parseIso(field.state.value, ISO_DATE)}
          disabled={props.disabled}
          placeholder={props.placeholder}
          aria-required={props.required === true || undefined}
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
          onChange={(date) => field.handleChange(formatIso(date, ISO_DATE))}
        />
      </Suspense>
    </FieldShell>
  );
}

export function DateTimeField(props: {
  label: string;
  required?: boolean;
  disabled?: boolean;
  placeholder?: string;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell label={props.label} required={props.required}>
      <Suspense fallback={<Skeleton className="h-9 w-full" />}>
        <DateTimePicker
          id={field.name}
          value={parseIso(field.state.value, ISO_DATE_TIME)}
          disabled={props.disabled}
          placeholder={props.placeholder}
          aria-required={props.required === true || undefined}
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
          onChange={(date) => field.handleChange(formatIso(date, ISO_DATE_TIME))}
        />
      </Suspense>
    </FieldShell>
  );
}

export function DateRangeField(props: { label: string; required?: boolean; disabled?: boolean }) {
  const field = useFieldContext<{ from: string; to: string }>();
  return (
    <FieldShell label={props.label} required={props.required}>
      <Suspense fallback={<Skeleton className="h-9 w-full" />}>
        <DateRangePicker
          id={field.name}
          value={{
            from: parseIso(field.state.value.from, ISO_DATE),
            to: parseIso(field.state.value.to, ISO_DATE),
          }}
          disabled={props.disabled}
          aria-required={props.required === true || undefined}
          aria-invalid={field.state.meta.errors.length > 0 || undefined}
          onChange={(range) =>
            field.handleChange({
              from: formatIso(range?.from, ISO_DATE),
              to: formatIso(range?.to, ISO_DATE),
            })
          }
        />
      </Suspense>
    </FieldShell>
  );
}

export function ComboboxField(props: {
  label: string;
  options?: ComboboxOption[];
  loadOptions?: (search: string) => Promise<ComboboxOption[]>;
  placeholder?: string;
  required?: boolean;
  disabled?: boolean;
}) {
  const field = useFieldContext<string>();
  return (
    <FieldShell label={props.label} required={props.required}>
      <Combobox
        value={field.state.value || undefined}
        onChange={(value) => field.handleChange(value ?? "")}
        options={props.options ?? []}
        loadOptions={props.loadOptions}
        placeholder={props.placeholder}
        disabled={props.disabled}
      />
    </FieldShell>
  );
}

export function MultiComboboxField(props: {
  label: string;
  options: ComboboxOption[];
  editable: boolean;
}) {
  const field = useFieldContext<string[]>();
  return (
    <FieldShell label={props.label}>
      {props.editable ? (
        <Suspense fallback={<Skeleton className="h-9 w-full" />}>
          <MultiCombobox
            values={field.state.value}
            onChange={(values) => field.handleChange(values)}
            options={props.options}
          />
        </Suspense>
      ) : (
        <div className="flex flex-wrap gap-1">
          {field.state.value.length === 0 ? (
            <span className="text-sm text-muted-foreground">—</span>
          ) : (
            field.state.value.map((name) => (
              <Badge key={name} variant="secondary">
                {name}
              </Badge>
            ))
          )}
        </div>
      )}
    </FieldShell>
  );
}

/** onSubmitAsync 返回的 form 键落 state.errorMap.onSubmit;\n 拆多条渲染。 */
function FormErrors() {
  const form = useFormContext();
  return (
    <form.Subscribe selector={(state) => state.errorMap.onSubmit}>
      {(onSubmit) => {
        const message = typeof onSubmit === "string" ? onSubmit : undefined;
        return <FormErrorSummary errors={message ? message.split("\n") : []} />;
      }}
    </form.Subscribe>
  );
}

const { useAppForm: useAppFormBase, withForm } = createFormHook({
  fieldContext,
  formContext,
  fieldComponents: {
    TextField,
    NumberField,
    SwitchField,
    SelectField,
    DateField,
    DateTimeField,
    DateRangeField,
    ComboboxField,
    MultiComboboxField,
  },
  formComponents: { FormErrors },
});

/** 提交结束后把焦点移到第一个仍有错误的字段;取不到 DOM 元素(如自定义组件未转发 id)则顺延到
 * 下一个可聚焦的错误字段。字段输入的 id 约定为 field.name(内置字段组件已遵守)。「第一个」按
 * fieldMeta 的字段注册序(≈挂载序/tab 序);条件渲染或重排字段的极端场景下未必是视觉最上者。 */
function focusFirstInvalidField(form: {
  state: { fieldMeta: Record<string, { errors?: unknown[] } | undefined> };
}): void {
  for (const [name, meta] of Object.entries(form.state.fieldMeta)) {
    if (!meta?.errors?.length) continue;
    const el = document.getElementById(name);
    if (el) {
      el.focus();
      return;
    }
  }
}

const patchedForms = new WeakSet<object>();

/**
 * 包装 useAppFormBase:提交前注入服务端错误清理(见 clearServerSubmitErrors),提交结束后聚焦
 * 首错字段(见 focusFirstInvalidField)。WeakSet 守卫而不是 useState/useRef，后者初始化器在
 * StrictMode 下双调用,保证不了只 patch 一次。
 */
export const useAppForm: typeof useAppFormBase = (opts) => {
  const form = useAppFormBase(opts);
  if (!patchedForms.has(form)) {
    patchedForms.add(form);
    const original = form.handleSubmit;
    form.handleSubmit = ((submitMeta?: unknown) => {
      clearServerSubmitErrors(form as unknown as ServerErrorForm);
      const result = submitMeta === undefined ? original() : original(submitMeta as never);
      return result.then(() => {
        focusFirstInvalidField(form as unknown as Parameters<typeof focusFirstInvalidField>[0]);
      });
    }) as typeof form.handleSubmit;
  }
  return form;
};

export { withForm };

import { useLocalization } from "@jcoder/abp-react/react";
import { Pencil } from "lucide-react";
import type { ReactNode } from "react";
import { SubmitButton } from "@/components/form/submit-button";
import { Button } from "@/components/ui/button";
import { Sheet, SheetContent, SheetFooter, SheetHeader, SheetTitle } from "@/components/ui/sheet";

export type SheetFormMode = "create" | "edit" | "view";

export interface SheetFormProps {
  mode: SheetFormMode;
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  onSubmit?: () => void;
  canEdit?: boolean;
  onEdit?: () => void;
  pending?: boolean;
  children: ReactNode;
}

/** 三态侧滑表单容器（对标 DrawerForm）。 */
export function SheetForm(props: SheetFormProps) {
  const L = useLocalization();
  const editable = props.mode !== "view";
  return (
    <Sheet open={props.open} onOpenChange={props.onOpenChange}>
      <SheetContent className="flex w-full flex-col gap-0 sm:max-w-md">
        <SheetHeader className="flex-row items-center justify-between gap-2 pr-12">
          <SheetTitle>{props.title}</SheetTitle>
          {!editable && props.canEdit === true && (
            <Button
              type="button"
              variant="ghost"
              size="icon"
              className="size-8"
              aria-label={L("Form:Edit")}
              onClick={props.onEdit}
            >
              <Pencil />
            </Button>
          )}
        </SheetHeader>
        <form
          className="flex flex-1 flex-col overflow-y-auto"
          onSubmit={(event) => {
            event.preventDefault();
            props.onSubmit?.();
          }}
        >
          <div className="flex-1 space-y-4 px-4 py-2">{props.children}</div>
          {editable && (
            <SheetFooter>
              <SubmitButton pending={props.pending} />
              <Button type="button" variant="outline" onClick={() => props.onOpenChange(false)}>
                {L("Form:Cancel")}
              </Button>
            </SheetFooter>
          )}
        </form>
      </SheetContent>
    </Sheet>
  );
}

import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

/** 放进 `<div className="divide-y rounded-lg border bg-card">` 容器里连排，分区线由容器 divide-y 画。 */
export function FormSection(props: {
  title: string;
  description?: string;
  children: ReactNode;
  className?: string;
}) {
  return (
    <div className={cn("grid gap-4 p-6 md:grid-cols-[220px_1fr] md:gap-8", props.className)}>
      <div>
        <h3 className="text-sm font-semibold">{props.title}</h3>
        {props.description !== undefined && (
          <p className="mt-1.5 text-xs leading-relaxed text-muted-foreground">
            {props.description}
          </p>
        )}
      </div>
      <div className="min-w-0 space-y-4">{props.children}</div>
    </div>
  );
}

import { cn } from "@/lib/utils";

/**
 * 必填字段 label 后的星号标记。仅视觉提示（`aria-hidden`），真正的必填语义由 input 自身的
 * `required`/`aria-required` 承载，标记不再对读屏播报，避免「星号 + required」重复念两遍。
 */
export function RequiredMark({ className }: { className?: string }) {
  return (
    <span aria-hidden className={cn("ml-0.5 select-none text-destructive", className)}>
      *
    </span>
  );
}

export type FieldErrors = { field?: string; message: string }[];

/** `onSubmitAsync` 校验器的返回形状:`form` 落表单级(state.errorMap.onSubmit)、`fields` 落各字段(field.state.meta.errors)。 */
export interface ServerErrorMap {
  form?: string;
  fields: Record<string, string>;
}

/** 通用 FieldErrors → onSubmitAsync 返回形状;空输入返回 null(表示校验通过)。 */
export function toErrorMap(errors: FieldErrors): ServerErrorMap | null {
  if (errors.length === 0) return null;
  const fields: Record<string, string> = {};
  const formLevel: string[] = [];
  for (const error of errors) {
    if (error.field) {
      fields[error.field] = fields[error.field]
        ? `${fields[error.field]}\n${error.message}`
        : error.message;
    } else {
      formLevel.push(error.message);
    }
  }
  const map: ServerErrorMap = { fields };
  if (formLevel.length > 0) map.form = formLevel.join("\n");
  return map;
}

/**
 * 把「提交 + 服务端错误落字段」封装成一个 onSubmitAsync 校验器。`mapError` 是
 * 后端协议注入点(不认识任何具体后端;ABP 版实现见 components/abp/crud/abp-form-errors)。
 * mapError 映射不出错误(非校验类失败)时回退 Error.message 作表单级错误,绝不静默吞掉。
 */
export function serverSubmitValidator<TValue>(
  submit: (value: TValue) => Promise<void>,
  mapError: (error: unknown) => FieldErrors,
) {
  return async ({ value }: { value: TValue }): Promise<ServerErrorMap | null> => {
    try {
      await submit(value);
      return null;
    } catch (error) {
      const mapped = toErrorMap(mapError(error));
      if (mapped) return mapped;
      return {
        form: error instanceof Error ? error.message : String(error),
        fields: {},
      };
    }
  };
}

import { useLocalization } from "@jcoder/abp-react/react";
import { Loader2 } from "lucide-react";
import type { ReactNode } from "react";
import { Button } from "@/components/ui/button";

export function SubmitButton({ pending, children }: { pending?: boolean; children?: ReactNode }) {
  const L = useLocalization();
  return (
    <Button type="submit" disabled={pending}>
      {pending === true && <Loader2 className="animate-spin" />}
      {children ?? L("Form:Save")}
    </Button>
  );
}

import { useLocalization } from "@jcoder/abp-react/react";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";

export function FormErrorSummary({ errors }: { errors: string[] }) {
  const L = useLocalization();
  if (errors.length === 0) return null;
  return (
    <Alert variant="destructive">
      <AlertTitle>{L("Form:SubmitFailed")}</AlertTitle>
      <AlertDescription>
        {errors.map((message) => (
          <p key={message}>{message}</p>
        ))}
      </AlertDescription>
    </Alert>
  );
}

